package com.novabank.payment.service;
import com.novabank.payment.domain.PaymentOrder; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.time.Instant; import java.util.UUID;
@Component public class RiskClient {private final RestClient client;private final com.novabank.payment.security.JwtService jwt;public RiskClient(@Qualifier("riskRestClient")RestClient c,com.novabank.payment.security.JwtService j){client=c;jwt=j;}
 public RiskDecision assess(PaymentOrder p,String auth){var q=new RiskRequest(p.getCustomerId(),"payment:"+p.getId(),p.getPaymentType().name(),p.getAmount(),p.getSourceAccountId(),p.getDestinationCardId(),p.getExternalPayeeId()!=null,0,false,0,Instant.now(),p.getCorrelationId());return client.post().uri("/api/risk/internal/assessments").header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt.createInternalAccessToken(p.getCustomerId())).body(q).retrieve().body(RiskDecision.class);}
 public record RiskRequest(UUID customerId,String operationReference,String operationType,java.math.BigDecimal amount,UUID accountId,UUID cardId,boolean newExternalPayee,int recentFailures,boolean recentlyChangedCard,int recentDisputes,Instant occurredAt,UUID correlationId){}
 public record RiskDecision(UUID assessmentId,UUID customerId,String operationReference,int riskScore,String decision,java.util.List<String> triggeredRuleCodes,String customerSafeReason,String internalAnalystExplanation,String ruleVersion,Instant timestamp,UUID correlationId){}
}
